body_md:
Fix $h$, $m>0$ and an initial set $ E_0 \subset \mathbb{T}^2$ with finite perimeter and such that $|E_0|=m$.

	Let $(E_h^n)_{n \in \mathbb{N}}$ be a discrete flow starting from $E_0$ and let $P_\infty$ be the limit of the non-increasing sequence $P(E_h^n)$. Then either one of the following holds: 
	\begin{itemize}
		\item[i)] $(E_h^n)_{n \in \mathbb{N}}$ converges to a disjoint union of $l$ discs of equal radii and total area $m$, where $l=\pi^{-1} (4m)^{-1}P_{\infty}^2 \in \mathbb{N}$;
		\item[ii)] $\left((E_h^n)^c\right)_{n \in \mathbb{N}}$ converges to a disjoint union of $l$ discs of equal radii and total area $1-m$, where $l=\pi^{-1} (4-4m)^{-1}P_{\infty}^2 \in \mathbb{N}$;


        \item[iii)]{\textcolor{black}{
		$(E_h^n)_{n \in \mathbb{N}}$ converges to a disjoint union of $l$ lamellae of total area $m$, with the same slope and $l\le P_{\infty}/2$.
        Moreover, the equality $l=P_{\infty}/2 \in \mathbb{N}$ holds if and only if the limit is given by vertical or horizontal lamellae.}}
	\end{itemize}
	In all cases the convergence is exponentially fast in $C^k$ for every $k \in N$.
	\label{teorema convergenza dimensione 2}

\label{teo alex}
	Let $E \subset \mathbb{T}^N$ be a strictly stable critical set.
	There exist $\delta \in(0,1/2)$ and $C>0$ with the following property: for any $f\in C^1(\partial E)\cap H^2(\partial E)$ such that $\|f\|_{C^1(\partial E)}\leq \delta$ and satisfying
	\begin{equation}
		\left |\int_{\partial E} f\,\textnormal{d} \mathcal{H}^{N-1}\right |\le \delta \|f\|_{L^2(\partial E)},\qquad \left |\int_{\partial E} f\nu_E\,\textnormal{d} \mathcal H^{N-1}\right|\leq \delta \|f\|_{L^2(\partial E)},
		\label{ipotesi alex}
	\end{equation}
	we have 
	\begin{equation}
		\|f\|_{H^1(\partial E)}\leq C\|H_{E_f}-\overline H_{E_f}\|_{L^2(\partial E)}.
		\label{e:aleq_gen}
	\end{equation}

Let $E$ be a set of class $C^1$.
	Given a function $f:\partial E \to \mathbb{R}$ such that $\|f\|_{L^{\infty}(\partial E)}$ is sufficiently small, we set
	\begin{equation}
		\label{normal_deformation}
		\partial E_f:=\{ x+f(x)\nu_E(x) : x\in \partial E \}
	\end{equation}
	and we call $E_f$ the \textit{normal deformation} of $E$ induced by $f$.

\label{definizione convergenza C^1}
	Given $\alpha\in [0,1]$, a sequence $(E_n)_{n\in\mathbb{N}}$ of $C^{1,\alpha}-$regular sets is said to converge in $C^{1,\alpha}$ to a set $E$ if:
	\begin{itemize}
		\item for any $x\in \partial E$, up to rotations and relabelling the coordinates, we can find a cylinder $C=B'\times (-1,1)$, where $B'\subset \mathbb{R}^{N-1}$ is the unit ball centred at the origin, and functions $f,f_n\in C^{1,\beta}(B';(-1,1))$ such that for $n$ large enough, it holds
		\begin{align*}
			(E-x)\cap C&=\{ (x',x_N)\in B'\times (-1,1)\ :\ x_N\le f (x')  \}\\
			(E_n-x)\cap C&=\{ (x',x_N)\in B'\times (-1,1)\ :\ x_N\le f_n (x')  \};    \end{align*}
		\item it holds 
		\[ f_n\to f\quad \text{in } C^{1,\alpha}(B').  \]
	\end{itemize}

\label{teorema convergenza C^1}
	Let $\Lambda >0$ and let $E$ be a set of class $C^2$. Then for every $\varepsilon>0$, there exists $\delta=\delta(\varepsilon,E)>0$ with the following property: for every $\Lambda-$minimizer $F$ such that $|E\triangle F|\le \delta$, then $F$ is of class $C^{1,1/2}$ and
	\[\textnormal{dist}_{C^{1,\beta}}(E,F) \le \varepsilon\quad \text{for} \quad \beta\in (0,1/2). \]

\label{definizione strictly stable set}
	We say that a regular critical set $E$ is \textit{a strictly stable set} if it has positive second variation of the perimeter, in the sense that 
	\[\delta^2P(E)[\varphi]>0,\qquad \forall \varphi \in T^{\perp} (\partial E) \setminus \{0\}.\]

Setting $Q:=\left(  1+ \sum_{j=1}^{N-1} \dfrac{(\partial_{v_j} f)^2}{(1+\kappa_j f)^2} \right)^{1/2}$, the following formulas hold true:
	\begin{enumerate}
		\item If $f\in L^\infty(\partial E)\cap H^1(\partial E)$ with $\|f\|_{L^\infty}$ sufficiently small, then
		\[ P(E_f)=\int_{\partial E}Q\prod_{i=1}^{N-1}(1+\kappa_i f) \,\textnormal{d} \mathcal H^{N-1}. \]
		\item If $f\in L^{\infty}(\partial E)\cap H^1(\partial E)$ with $\|f\|_{L^\infty} $ sufficiently small, then the first variation $\delta P(E_f)[\varphi]$ exists for all $\varphi\in C^1(\partial E)$ and is given by
		\begin{align}
			\delta P(E_f)[\varphi]
			=&\int_{\partial E} \varphi \,Q\sum_{i=1}^{N-1}\kappa_i\prod_{j\neq i}(1+\kappa_j f)  \,\textnormal{d}\mathcal H^{N-1} \nonumber\\
			&+\int_{\partial E}\dfrac 1Q\prod_{i=1}^{N-1}(1+\kappa_i f) \left (\sum_{j=1}^{N-1}\frac{\partial_{v_j} \varphi \,  \partial_{v_j} f}{(1+k_j f)^2} -
			\varphi\,\sum_{j=1}^{N-1}\frac{ k_j\,(\partial_{v_j} f)^2}{(1+k_j f)^3}\right)\,\textnormal{d}\mathcal H^{N-1}.
			\label{variaz_gen}
		\end{align}
	\end{enumerate}

\label{oss}
	We observe that, if $\|f\|_{L^{\infty}(\partial E)}$ is small enough and $|E_f|=|E|$, then there exists a constant $ C>0$, only depending on $E$, such that
	\begin{equation}
		\left |\int_{\partial E}f(x)\,\textnormal{d}\mathcal H^{N-1}(x)\right|\leq  C\int_{\partial E} f(x)^2\,\textnormal{d}\mathcal H^{N-1}(x).
		\label{conto media curvatura non nulla}
	\end{equation}  
	Firstly, since $\partial E$ is regular, for every $\varepsilon >0$ sufficiently small there exists a tubular neighborhood $\mathcal{N}$ of $\partial E$ such that $\mathcal{N}$ is diffeomorphic to $\partial E\times (-\varepsilon,\varepsilon)$ via the diffeomeorphism $\Psi(x,t)=x+\nu_E(x)t$.
	The Jacobian of $\Psi$ is given by
	\begin{equation}\label{quiquo}
		J\Psi(x,t)=\prod_{i=1}^{N-1}(1+\kappa_i(x) t). 
	\end{equation} 
	Secondly, if $\|f\|_{L^{\infty}(\partial E)}$ is small enough, we remark that the condition $|E_f|=|E|$ is equivalent to
	\[ 0=|E_f|-|E|=\int_{\partial E}\int_0^{f(x)}J\Psi(x,t)\,\textnormal{d} t\,\textnormal{d} \mathcal H^{N-1}(x). \] 
	Then, we can conclude that
	\begin{align*}
		0&=\int_{\partial E}\int_0^{f(x)}J\Psi(x,t)\,\textnormal{d} t\,\textnormal{d} \mathcal H^{N-1}(x)\\
		&=\int_{\partial E}f(x)\,\textnormal{d}\mathcal H^{N-1}(x)+\int_{\partial E}\int_0^{f(x)}(J\Psi(x,t)-1) \,\textnormal{d} t\,\textnormal{d} \mathcal H^{N-1}(x)  \\
		&= \int_{\partial E}f(x)\,\textnormal{d}\mathcal H^{N-1}(x)+\int_{\partial E}\int_0^{f(x)} (H_E(x) \, t + o(t))\,\textnormal{d} t \,\textnormal{d}\mathcal H^{N-1}(x),
	\end{align*}
	that implies \eqref{conto media curvatura non nulla} for a constant depending only on $N$ and the principal curvatures of $E$.

Fix $N\geq 2$.
	There exists $\delta=\delta(E)>0$ small such that, if $f\in L^{\infty}(\partial E)\cap H^1(\partial E)$ with $\|f\|_{L^\infty(\partial E)}\le \delta$,
	\begin{equation}\label{1988}
		\left\lvert\int_{\partial E} f(x)\,\textnormal{d} \mathcal H^{N-1}(x)\right\rvert\leq \delta \|f\|_{L^2(\partial E)} \quad \text{and} \quad
		\left \lvert\int_{\partial E} f(x)\nu_E(x)\,\textnormal{d} \mathcal H^{N-1}(x)\right \rvert\leq \delta \|f\|_{L^2(\partial E)},
	\end{equation}
	then we have
	\begin{equation*}
		\delta^2 P(E)[f]=\int_{\partial E}(|\nabla f(x)|^2-|B_E(x)|^2 f(x)^2)\,\textnormal{d}\mathcal H^{N-1}(x)\geq \frac{m_0}{8} \|f\|_{H^1(\partial E)}^2,
	\end{equation*}
	where $m_0$ is the constant given by Lemma \ref{Lemma_3.6_AFM}.
	\label{lemma 1.4}

First of all we notice that, if we take the constant $C$ in \eqref{e:aleq_gen} to be bigger than $\sqrt{P(E)/2}$, then it is enough to consider only the case $\|H_{E_f}-\overline H_{E_f}\|_{L^2(\partial E)}\leq 1$. 


	Set $p=x+f(x)\nu_E(x)$ and let $\varphi \in C^1(\partial E)$, by the definition of scalar mean curvature $H_{E_f}$ and a change of coordinates we obtain
	\begin{equation}
		\delta P(E_f)[\varphi]=\int_{\partial E} (H_{E_f}\nu_{E_f})(p)\cdot \nu_E\,\varphi\, J\Phi\,\textnormal{d} \mathcal H^{N-1}.
		\label{def_variaz_gen}
	\end{equation}
	Combining \eqref{def_variaz_gen}, \eqref{Jac_gen} and \eqref{prod scal vers normali} we obtain
	\[\delta P(E_f)[\varphi]=\int_{\partial E}H_{E_f}\varphi\,J\Phi\left(  1+ \sum_{j=1}^{N-1} \dfrac{(\partial_{v_j} f)^2}{(1+\kappa_j f)^2} \right)^{-1/2} \,\textnormal{d} \mathcal H^{N-1}=\int_{\partial E}H_{E_f}\varphi \prod_{i=1}^{N-1}(1+\kappa_i f)\,\textnormal{d}\mathcal H^{N-1}.\]
	In the following, with a slight abuse of notation, with the symbol $O(g)$ we will mean any function $h$ of the form $h(x)=r(x)g(x)$, where $|r(x)|\le C$ for all $x\in \partial E$ and $C$ is a constant depending only on $N$ and $E$.


	By a simple Taylor expansion we have
	\begin{equation}
		\delta P(E_f)[\varphi]=\int_{\partial E}H_{E_f}\varphi\,\left(1+H_E f+O(f^2)  \right) \,\textnormal{d} \mathcal H^{N-1}. 
		\label{cp_1_1_gen}
	\end{equation}
	From \eqref{variaz_gen} and again by Taylor expansion, we obtain
	\begin{align}
		\delta P(E_f)[\varphi]=&\int_{\partial E} \left (H_E +f\sum_{i=1}^{N-1} \kappa_i \sum_{s\ne i} \kappa_s  + O(f^2)  + O(| \nabla f |^2)\right)\varphi\,\textnormal{d} \mathcal H^{N-1}   \nonumber\\
		&+\int_{\partial E}(\nabla f + h) \cdot \nabla \varphi\,\textnormal{d}\mathcal H^{N-1}\nonumber\\
		=&  \int_{\partial E} \left( H_E +f H^2_E -|B_E|^2f + O(f^2)  + O(| \nabla f |^2)  \right) \varphi  \,\textnormal{d} \mathcal H^{N-1} \nonumber\\
		&+\int_{\partial E}(\nabla f + h) \cdot \nabla \varphi\,\textnormal{d}\mathcal H^{N-1}
		\label{cp_2_gen}
	\end{align}
	where $\nabla f,\nabla \varphi$ are respectively the tangent gradient of $f,\varphi$ on $\partial E$  and  $h$ is a vector field satisfying $|h|\leq C(|f|+|\nabla f|^2))|\nabla f|$.
	Set $R=O(f^2)+O(|\nabla f|^2)$, by comparing \eqref{cp_1_1_gen} and \eqref{cp_2_gen} we infer that
	\begin{align}
		\int_{\partial E}(\nabla f\cdot\nabla \varphi-|B_E|^2 f\varphi) \,\textnormal{d}\mathcal H^{N-1}\nonumber =&\int_{\partial E}(H_{E_f}-H_E) \left(1+H_E f+ R\right)\varphi\,\textnormal{d}\mathcal H^{N-1} \nonumber\\
		&-\int_{\partial E}  (h\cdot\nabla \varphi+(O(f^2)+O(|\nabla f|^2))\varphi) \,\textnormal{d}\mathcal H^{N-1}.
		\label{eq_lin3_gen}
	\end{align}
	Testing \eqref{eq_lin3_gen} with $\varphi=1$, we get
	\begin{align*}
		\int_{\partial E} (H_{E_f}-H_E)\left( 1+H_E f + R \right)\,\textnormal{d}\mathcal H^{N-1}
		=\int_{\partial E}(O(|f|)+O(|\nabla f|^2))\,\textnormal{d} \mathcal H^{N-1},

	\end{align*}
	then, for $\delta$ sufficiently small, using Hölder inequality we obtain 
	\begin{align*}
		\left| \overline H_{E_f}-H_E \right|
		&=\left|-\fint_{\partial E}  (H_{E_f}-H_E)(H_E f+R)\,\textnormal{d}\mathcal H^{N-1} + \fint_{\partial E}(O(|f|)+O(|\nabla f|^2))\,\textnormal{d} \mathcal H^{N-1}\right|\\
		&\le \left| \fint_{\partial E}  (H_{E_f}-\overline H_{E_f})(H_E f+R)\,\textnormal{d}\mathcal H^{N-1} \right| + \left| \fint_{\partial E}  (\overline H_{E_f}-H_E) (H_E f+R)\,\textnormal{d}\mathcal H^{N-1} \right| \\
		&\ \ + \int_{\partial E}(O(|f|)  +O(|\nabla f|^2))\,\textnormal{d} \mathcal H^{N-1}\\
		&\le \delta\, \dfrac{|H_E|+C\delta}{P(E)}\|H_{E_f}-\overline H_{E_f}\|_{L^2}+\delta  \left(|H_E|+C\delta \right )|\overline H_{E_f}-H_E|\\
		&\ \ + \int_{\partial E}(O(|f|) +O(|\nabla f|^2))\,\textnormal{d} \mathcal H^{N-1},
	\end{align*}
	with $C=C(N,E)$ since $\delta\le 1$. 
	For $\delta $ small enough, recalling that $\|H_{E_f} - \overline H_{E_f}\|_{L^2}\leq1$, the previous inequality implies
	\begin{equation}
		\frac 12 |\overline H_{E_f}-H_E|\le  C\delta \|H_{E_f}-\overline H_{E_f}\|_{L^2}+ \int_{\partial E}(O(|f|)  +O(|\nabla f|^2))\,\textnormal{d} \mathcal H^{N-1} \le C\delta.
		\label{eq_lin7_gen}
	\end{equation}
	Using the bound $\|f\|_{C^1}\leq \delta$ and the definition of $h$ we easily see that
	\[h\cdot\nabla f=\delta \,O(|\nabla f|^2) . \]
	Testing \eqref{eq_lin3_gen} with $\varphi=f$, using Hölder's inequality and by the previous remark, we get
	\begin{align}
		\label{fine_catena_gen}
		\int_{\partial E} (|\nabla f|^2&-|B_E|^2 f^2)\,\textnormal{d}\mathcal H^{N-1}\nonumber = \int_{\partial E}\left(  H_{E_f}-H_E \right)( 1+H_E f + R)f\,\textnormal{d}\mathcal H^{N-1}\nonumber\\
		&+\delta\int_{\partial E}(O(f^2) +O(|\nabla f|^2))\,\textnormal{d} \mathcal H^{N-1}\nonumber\\
		=& \int (H_{E_f}-\overline H_{E_f})(1+H_E f + R)f\,\textnormal{d}\mathcal H^{N-1}\nonumber+\int(\overline H_{E_f}-H_E)(1+H_E f + R)f\,\textnormal{d}\mathcal H^{N-1}\nonumber\\
		& +\delta\int_{\partial E}(O(f^2) +O(|\nabla f|^2))\,\textnormal{d} \mathcal H^{N-1}\nonumber\\
		\leq&\, C\|H_{E_f}-\overline H_{E_f}\|_{L^2}\|f\|_{L^2}+ \nonumber |\overline H_{E_f}-H_E|\int (1+H_E f + R)f\,\textnormal{d}\mathcal H^{N-1}\nonumber\nonumber\\
		&+\delta\int_{\partial E}(O(f^2) +O(|\nabla f|^2))\,\textnormal{d} \mathcal H^{N-1}\nonumber\\
		=&\, C\|H_{E_f}-\overline H_{E_f}\|_{L^2}\|f\|_{L^2}+|\overline H_{E_f}-H_E|\int (f+O(f^2)+f O(|\nabla f|^2))\,\textnormal{d}\mathcal H^{N-1}\nonumber\\
		&+\delta\int_{\partial E}(O(f^2) +O(|\nabla f|^2))\,\textnormal{d} \mathcal H^{N-1}.
	\end{align}
	By \eqref{conto media curvatura non nulla}, \eqref{eq_lin7_gen} and by Hölder inequality, we obtain
	\[|\overline H_{E_f}-H_E|\int (f+O(f^2)+f O(|\nabla f|^2))\,\textnormal{d}\mathcal H^{N-1}  \le  \delta \int_{\partial E}(O(f^2)+O(|\nabla f|^2)).\]
	Finally, by the above inequality, \eqref{conto media curvatura non nulla} again and by combining \eqref{fine_catena_gen} with \eqref{eq_lin7_gen} 
	we deduce that, for any $\eta>0$, it holds 
	\begin{align}
		\int_{\partial E}(|\nabla f|^2-|B_E|^2 f^2)\,\textnormal{d} \mathcal H^{N-1}&\leq C\|H_{E_f}-\overline H_{E_f}\|_{L^2}\|f\|_{H^1}+\delta \int_{\partial E}(O( f^2)+O(|\nabla f|^2))\,\textnormal{d} \mathcal H^{N-1}\nonumber\\
		&\leq \dfrac 1{\eta} C^2\|H_{E_f}-\overline H_{E_f}\|_{L^2}^2+\eta\|f\|_{H^1}^2+C\delta \|f\|_{H^1}^2.
		\label{fine_gen}
	\end{align}
	The conclusion then follows combining \eqref{fine_gen} with Lemma \ref{lemma 1.4} and taking $\delta$ and $\eta$ sufficiently small.

For some particular choices of the set $E$, a geometric explanation of the condition  
	\begin{equation}
		\left \lvert\int_{\partial E} f\nu_E\,\textnormal{d} \mathcal H^{N-1}\right \rvert\leq \delta \|f\|_{L^2}
		\label{condition strange}
	\end{equation}
	can be found. It is the case for the ball, the cylinder or the lamella. For example consider $E=B_r$, the case where $E$ is a cylinder or a lamella being analogous. We show that in this case condition \eqref{condition strange} follows from enforcing 
	\[\text{bar}(E_f)=\text{bar}(B_r)=0.\]
	Indeed, consider the case $r=1$ for simplicity, the barycenter in polar coordinates is given by
	\[0=\dfrac 1{(N+1)\omega_N}\int_{\partial B} (1+f)^{N+1}x\,\textnormal{d}\mathcal H^{N+1}\]
	and thus, by a simple Taylor expansion, we obtain
	\begin{align*}
		0&=\int_{\partial B} \left( 1+(N+1)f+\frac 12 R f^2 \right) x \,\textnormal{d} \mathcal H^{N-1}\nonumber \\
		&=(N+1)\int_{\partial B} f(x)x   \,\textnormal{d} \mathcal H^{N-1} +\frac12\int_{\partial B} xRf^2    \,\textnormal{d} \mathcal H^{N-1}
	\end{align*}
	where $ |R(x)|\leq C(N)$ for every $x\in\partial B.$
	We can then estimate
	\[     \left\lvert\int_{\partial B} f(x)x\,\textnormal{d} \mathcal H^{N-1}  \right\rvert\leq C\|f\|_{L^2}^2 \] provided $\|f\|_{C^1}\le \delta$ and the conclusion follows recalling $\nu_B(x)=x$.

\label{oss limitatezza perimetro}
	We start by remarking that the sequence of the perimeters along the discrete flow is non-increasing. Indeed, from the minimality of $E_h^n$ and considering $E^{n-1}_h$ as a competitor we obtain
	\[ P(E_h^n)\le P(E_h^n)+\frac{1}{h}\int_{E^{n-1}_h \triangle E^n_h} \textnormal{dist}_{\partial E^{n-1}_h}(x) \,\textnormal{d} x\le P(E^{n-1}_h). \]
	From this simple remark we observe that, even if the starting set of the flow $E_0$ is not of finite perimeter, the perimeters of the sets $E_h^n$ are uniformly bounded by a constant that only depends on the dimension $N$, the fixed volume $m$ and $h$. Given any set $E_0$ of volume $m$, consider the cube $Q_m$ of the same volume. From the minimality of $E_h^1$ and using $Q_m$ as a competitor we obtain 
	\begin{align*}
		P(E^1_h)&\le P(Q_m)+\frac 1h \int_{E_0\triangle Q_m}\textnormal{dist}_{\partial E_0}(x) \,\textnormal{d} x-\frac 1h \int_{E_0\triangle E_1^h}\textnormal{dist}_{\partial E_0}(x) \,\textnormal{d} x\\
		&\le P(Q_m) + \dfrac 1h\int_{\mathbb{T}^N}\sqrt{N}=C(N,m,h),
	\end{align*}
	where we estimated $\textnormal{dist}_{\partial E_0}\le \text{diam}(\mathbb{T}^N)=\sqrt N$.

\label{proprieta flusso}
	Let $h,$ $m$, $M>0$ and let $E \subset \mathbb{T}^N$ be a set with $\lvert E \rvert =m$ and $P(E)\le M$.  Then, any solution $F \subset \mathbb{T}^N$ to \eqref{pb_min_1} satisfies the following regularity properties:
	\begin{itemize}
		\item[i)] There exist $c_0=c_0(N)>0$ and a radius $r_0=r_0(m,h,N,M)>0$ such that for every $x \in \partial^* F$ and $r \in (0,r_0]$ we have
		\begin{equation*}
			\lvert B_r(x) \cap F \rvert \ge c_0 r^N \quad \text{and} \quad \lvert B_r(x) \setminus F \rvert \ge c_0 r^N.
		\end{equation*}
		In particular, $F$ admits an open representative whose topological boundary coincides with the closure of its reduced boundary, i.e. $\partial F= \overline{\partial^* F}$.

		\item[ii)] There exists $\Lambda=\Lambda(m,h,N,M)>0$ such that $F$ is a $\Lambda$-minimizer of the perimeter, that is
		\begin{equation*}
			P(F) \le P(F') + \Lambda \lvert F \triangle F' \rvert
		\end{equation*}
		for all measurable set $F' \subset \mathbb{T}^N$.

		\item[iii)] The following Euler-Lagrange equation holds: there exists $\lambda \in \mathbb{R}$ such that for all $X \in C^1_c(\mathbb{T}^N,\mathbb{T}^N)$ we have
		\begin{equation}
			\int_{\partial^*F}\dfrac {\textnormal{sd}_{ E}}h X\cdot \nu_F \,\textnormal{d} \mathcal{H}^{N-1}+\int_{\partial^* F} \textnormal{div}_{\tau} X \,\textnormal{d} \mathcal{H}^{N-1}=\lambda\int_{\partial^* F} X\cdot \nu_F  \,\textnormal{d} \mathcal{H}^{N-1}.
			\label{euler-lagrange equation}
		\end{equation}

		\item[iv)] There exists a closed set $\Sigma$,
		whose Hausdorff dimension is less than or equal to $N-8$, such that $\partial^* F= \partial F \setminus \Sigma$ is an $(N-1)$-submanifold of class $C^{2,\alpha}$ for all $\alpha \in (0,1)$ with
		\begin{equation*}
			\lvert H_{F}(x) \rvert \le \Lambda, \quad \text{for all } x \in \partial F \setminus \Sigma.
		\end{equation*}

		\item[v)] There exists $k_0=k_0(m,h,N,M)\in \mathbb{N}$ and $s_0=s_0(m,h,N,M)>0$ such that $F$ is made up of at most $k_0$ connected components having mutual Hausdorff distance at least $s_0$.

	\end{itemize}
	\label{prop regularity discrete flow}

\label{prop 3.1 rivisitata}
	Every stationary set $E$ for the discrete flow is a critical set of the perimeter.
	\\
	Viceversa, if $E$ is a {\textcolor{black}{regular}} critical set of the perimeter, then there exists $h^*=h^*(E)>0$ such that, for every $h<h^*$, the volume preserving discrete flow starting from $E$ is unique and given by $E_h^n=E.$
	Moreover, if $E$ is a strictly stable set then it is also the unique volume-constrained minimizer of the functional
	\begin{equation*}
		\tilde J_h(F):= P(F)+\frac{1}{h}\int_F \textnormal{dist}_E(x) \,\textnormal{d} x .
	\end{equation*}

The first statement is an immediate consequence of \eqref{euler-lagrange equation}. Since $E$ is a stationary point for the discrete flow, it satisfies
	\begin{equation*}
		\int_{\partial^* E}\textnormal{div}_{\tau} X \,\textnormal{d} \mathcal{H}^{N-1} =
		\lambda \int_{\partial^* E} X \cdot \nu_E\,\textnormal{d} \mathcal{H}^{N-1}
	\end{equation*}
	for all $X \in C^1_c(\mathbb{T}^N,\mathbb{T}^N)$, i.e. $E$ is a critical point for the perimeter.


	The second part follows using the same argument of the proof of \cite[Proposition~3.2]{MPS}. Indeed, recall that the second variation has the following expression
	\[ \partial^2 J_h(E)[\varphi]=\int_{\partial E} |\nabla \varphi|^2 + \left(  \dfrac 1h -|B_E|^2 \right) \varphi^2\,\textnormal{d}\mathcal H^{N-1}, \]
	which is positive if $h$ is small enough. Then we procede as in the proof of  \cite[Proposition~3.2]{MPS}.


	Analogously, we prove that $E$ is the unique volume-constrained minimizer of $\tilde J_h$. Firstly, observe that, by Theorem \ref{coroll 1.2}, $E$ is a strict local $L^1$-minimizer of the perimeter and it is a global minimizer of the second term in $\tilde J_h$. Therefore, there exists $\varepsilon>0$ such that \[\tilde J_h(E) <\tilde J_h(F) \] for all measurable set $F$ such that $|F|=|E|$ and $|E \triangle F|\le \varepsilon$, i.e. $E$ is an isolated local minimizer for $\tilde J_h$ in $L^1$ with the volume constraint, with minimality neighbourhood uniform with respect to $h$. Now, given any sequence $(h_n)_{n \in \mathbb{N}}$ going to zero, let $F_n$ be a volume constrained minimizer of $J_{h_n}$; we then easily deduce that $|E \triangle F_n| \to 0$ as $n \to \infty$, and therefore, for $n$ large enough, $|E\triangle F_n|\le \varepsilon$. The strict minimality of $E$ therefore implies  $F_n=E$.

Let $h^*=h^*(E)$ be the constant given by Proposition \ref{prop 3.1 rivisitata} so that, for every $h< h^*$, $E$ is the unique volume-constrained global minimizer of the functional 
	\begin{equation}
		\label{E_min_0}
		\tilde J_h(G):= P(G)+\frac{1}{h}\int_G \textnormal{dist}_{E}(x) \,\textnormal{d} x.
	\end{equation}
	Fix $h<h^*$ and let $(E_n)_{n \in \mathbb{N}}$ be a sequence of sets satisfying
	\begin{equation}
		|E_n|=|E|, \qquad \overline{E}_n \overset{H}{\to} \overline{E}.
		\label{ipotesi}  
	\end{equation}
	Consider $F_n$ a solution of \eqref{pb_min_1} with $E_n$ replacing $E$. We claim that
	\begin{equation*}
		F_n \overset{L^1}\to E.
	\end{equation*} 
	If we prove the claim, the conclusion easily follows. 


	First, Remark \ref{oss limitatezza perimetro} ensures that  $(F_n)_{n \in \mathbb{N}}$ is a sequence of  sets with uniformly bounded perimeters, with the bound depending only on $N,m,h$. Therefore, there exist $F$ a set of finite perimeter such that $|F|=m$ and a (unrelabelled) subsequence of $(F_n)_{n \in \mathbb{N}}$ such that 
	\begin{equation*}
		F_n\overset{L^1}\to F . 
	\end{equation*}
	Now, let $K$ be a compact subset of $\mathbb{T}^N$ such that, up to a subsequence, we have
	\begin{equation*}
		\overline{E_n^c} \overset{H}{\to} K.
	\end{equation*}
	From the second property in \eqref{ipotesi} we easily deduce that $(\overline E)^c \subset K$, and therefore $K^c\subset \overline E$. In particular, this inclusion implies that
	\begin{equation*}
		\int_{K^c} \textnormal{dist}_K(x) \,\textnormal{d} x= \int_E \textnormal{dist}_K(x) \,\textnormal{d} x \ge \int_G \textnormal{dist}_K(x) \,\textnormal{d} x
	\end{equation*}
	for every $G \subset \mathbb{T}^N$.
	Setting 
	\[\bar{J}_h(G):=P(G)+\frac{1}{h} \int_G (\textnormal{dist}_E(x)-\textnormal{dist}_{K}(x))\,\textnormal{d} x, \]
	from the previous remark and from the fact that $E$ is the unique minimizer of \eqref{E_min_0}, we have
	\begin{align*}
		\bar{J}_h(G)&= \tilde J_h(G)-\frac{1}{h}\int_G  \textnormal{dist}_K(x)\,\textnormal{d} x\\
		&>\tilde J_h(E)-\frac{1}{h}\int_G  \textnormal{dist}_K(x)\,\textnormal{d} x\\
		&\ge \tilde J_h(E)-\frac{1}{h}\int_E \textnormal{dist}_K(x)\,\textnormal{d} x=\bar{J}_h(E),
	\end{align*}
	for any measurable set $G\subset \mathbb{T}^N$ with $|G|=|E|$. Finally, we obtain
	\begin{align*}
		\bar{J}_h(F)&=P(F)+\frac 1h \int_{F} \left(\textnormal{dist}_E( x)-\textnormal{dist}_{K}(x)\right) \,\textnormal{d} x\\
		&\le \liminf_{n\to \infty} P(F_n) +\frac 1h \int_{F} \left(\textnormal{dist}_{E}( x)-\textnormal{dist}_{K}(x)\right) \,\textnormal{d} x\\
		&=\liminf_{n \to \infty} \left( P(F_n)+\frac 1h \int_{F_n} \left(\textnormal{dist}_{E_n}( x)-\textnormal{dist}_{E_n^c}(x)\right) \,\textnormal{d} x \right)\\
		&\le \liminf_{n\to \infty} \left( P(E)+\frac 1h \int_{E} \left(\textnormal{dist}_{E_n}( x)-\textnormal{dist}_{E_n^c}(x)\right) \,\textnormal{d} x \right)\\
		&=P(E)-\frac{1}{h}\int_E \textnormal{dist}_{K}(x)\,\textnormal{d} x=\bar{J}_h(E)
	\end{align*}
	where we exploited the lower-semicontinuity of the perimeter and the minimality of $F_n$.
	Since $E$ is the unique volume-constrained minimizer of $\bar{J}_h$, the set $F$ must coincide with $E$ and this concludes the proof.

\label{uniform L1 estimate}
	Let $E \subset \mathbb{T}^N$ be a strictly stable set. Then, for every $\varepsilon >0$ there exist $\delta^*=\delta^*(\varepsilon, E) >0$ and $h^*=h^*(E)>0$ with the following property: for every $h <  h^*$, if $E_0$ is a measurable set such that 
	\begin{equation*}
		|E_0| =|E|, \qquad \overline{E}_0\subset(E)_{\delta^*},
	\end{equation*} 
	then the discrete flow $(E_h^n)_{n \in \mathbb{N}}$ starting from $E_0$ satisfies \[\alpha(E,E^n_h) \le \varepsilon\]
	for every $n \in \mathbb{N}$ .

Let $m>0$ such that the ball  of volume $m$ has perimeter strictly less than the one of the lamella of the same volume; we remark that for every smaller volume $m'\le m$ the same property holds.
	Let $E$ be a lamella of measure $m$, recall that $E$ is a strictly stable set of the perimeter in $\mathbb{T}^N$. 
	From the assumption on $m$ it follows that $E$ is only a local minimizer of the perimeter and not a global one.\\
	\textbf{Step 1.} Firstly, we construct a sequence $(E_n)_{n \in \mathbb{N}}$ such that $E_n \to E$ in $L^1$ and $\partial E_n \to \mathbb{T}^N$ in the Hausdorff distance.
	We define $E_n$ by adding to $E$ some balls contained in $\mathbb T^N\setminus E$ and of overall small volume, and by subtracting to $E$ balls contained in $E$ with the same overall volume. 

	Recall that $\mathbb{T}^N=[0,1]^N/\mathbb{Z}^N$.
	In the following, with a little abuse of notation, we will identify $\mathbb{T}^N$ and $[0,1)^N$.
	We define
	\begin{align*}
		I_n:&=\left \{\underline k =(k_1,\ldots, k_N) \in \mathbb{Z}^N: \, 0\le k_i \le 2^{n}-1 \quad \forall i =1,\ldots N\right\},\\
		\mathcal{P}_n:&=\left \{Q_{n,\underline k}:=\Big[0,\frac{1}{2^n}\Big)^N+\frac{\underline k}{2^n}:\, \underline k \in I_n   \right \},
	\end{align*} 
	for every $n \in \mathbb{N}$. Up to choosing $m$ smaller, we can assume that $m=1/2^s$ for some $s \in \mathbb{N}$. Moreover, we can suppose, up to translations, that $E=[0,1)^{N-1} \times (0,1/2^s)$, thus for $n \ge s$ we have
	\[E =\textnormal{Int}\left ( \bigcup_{ \underline k  \in I_n, \,\,0\le k_N \le 2^{n-s}-1} Q_{n,\underline k}\right), \]
	where $\textnormal{Int}(\cdot)$ denotes the interior of a set in $\mathbb{T}^N$.





	For every $n\ge s$ and 
	$\underline k  \in I_n$, we consider the balls $B_{n,\underline k} \subset Q_{n,\underline k}$  centered in the center of the cube $Q_{n,\underline k}$ and of radius $r_{n,\underline k}$ chosen in such a way that
	\begin{equation}
		\label{misura_uguale}
		\left\lvert\bigcup_{\underline k   \in I_n,\, \,0\le k_N \le 2^{n-s}-1} B_{n,\underline k}\right\rvert= \left\lvert \bigcup_{\underline k   \in I_n, \,\,2^{n-s}\le k_N \le 2^{n}-1} B_{n,\underline k} \right\rvert.
	\end{equation}
	Moreover, we can also take the radii $r_{n,\underline k}$ sufficiently small so that
	\begin{equation}\lim_{n \to \infty}\left\lvert\bigcup_{\underline k  \in I_n} B_{n,\underline k}\right\rvert = 0, \qquad \lim_{n \to \infty}P   \left(\bigcup_{\underline k   \in I_n } B_{n,\underline k}\right)=0.
		\label{misura_va_zero}
	\end{equation}
	Set now
	\begin{align*} 
		A_n&:=\bigcup_{\underline k   \in I_n ,\,\,0\le k_N \le 2^{n-s}-1} B_{n,\underline k}\subset \textnormal{Int}\left (\bigcup_{\underline k   \in I_n ,\,\,0\le k_N \le 2^{n-s}-1} Q_{n,\underline k}\right)= E,\\ C_n&:=\bigcup_{\underline k   \in I_n ,\,\,2^{n-s}\le k_N \le 2^{n}-1} B_{n,\underline k}\subset \bigcup_{\underline k   \in I_n ,\,\,2^{n-s}\le k_N \le 2^{n}-1} Q_{n,\underline k}\subset \mathbb{T}^N\setminus E.
	\end{align*}
	Define $E_n=(E\cup C_n)\setminus A_n$ and observe that, by \eqref{misura_uguale}, we have $|E_n|=|E|$. Now, by \eqref{misura_va_zero}, we also obtain 
	\[ E_n\overset{L^1}{\to} E \quad \textnormal{ and } \quad P(E_n) \to P(E).\]
	Observe that, from the definition of $A_n$ and $C_n$, we have that
	\[(\partial A_n)_{\sqrt{N}/2^n} \cup (\partial C_n)_{\sqrt{N}/2^n}=\mathbb{T}^N\]
	and therefore the set $\partial E_n= \partial E \cup \partial C_n \cup \partial A_n$ converges in the Hausdorff metric to the whole $\mathbb{T}^N$  as $n\to +\infty$. Therefore we have constructed a sequence $(E_n)_{n \in \mathbb{N}}$ that satisfies
	\begin{equation}
		E_n\overset{L^1}{\to} E,\qquad  P(E_n) \to P(E), \qquad \partial E_n\overset{H}{\to} \mathbb{T}^N.
		\label{insiemi controesempio}
	\end{equation}

	\textbf{Step 2.} Let $E_n$ be the sets previously defined.
	We consider the space $X=\{  F\subset \mathbb{T}^N\,:\, F \text{ is measurable} \}$ endowed with the $L^1-$distance, i.e. $\textnormal{dist}_{L^1}(F,G)=|F\triangle G|$ for every $F,G\in X$. We extend our functional in the following way 
	\begin{equation*}
		\tilde J^E_h(F):=\begin{cases} J_h^E(F) &\text{if } P(F)<\infty,\ |F|=m,\\[1ex]
			+\infty  &\text{otherwise}\end{cases}
	\end{equation*}
	and we set $J_n:=\tilde J_h^{E_n}$. We then prove the $\Gamma-$convergence of the functionals $J_n$ to the perimeter functional in $X$, that is
	\begin{equation}
		\Gamma(X)-\lim_{n \to \infty}J_n=P.
		\label{gamma-convergence}
	\end{equation}

	We can clearly restrict ourselves to consider sets of finite perimeter and volume $m$, otherwise the result is trivial. For any given set $F$ of measure $m$ and finite perimeter we choose the sequence constantly equal to $F$ as a recovery sequence for $F$. Indeed, by~\eqref{insiemi controesempio} we have
	\[ J_n(F)=P(F)+\frac 1h \int_{F\triangle E_n} \textnormal{dist}_{\partial E_n}\to P(F).\]
	We now prove the $\liminf$ inequality. Given a sequence $F_n$ that converges to $F$ in $L^1$, by the $L^1-$semicontinuity of the perimeter, we have
	\[ P(F)\le \liminf_{n\to \infty} P(F_n)\le \liminf_{n\to \infty} \left(    P(F_n)+\frac 1h \int_{F_n\triangle E_n}\textnormal{dist}_{\partial E_n}     \right)\]
	and thus \eqref{gamma-convergence} is proved.

	Therefore, thanks to the equi-coercivity of the functionals $J_n$, any sequence of volume-constrained global minimizers of $J_n$ converges in $L^1$, up to a subsequence, to a volume-constrained global minimizer of the perimeter in the torus. Let $(F_n)_{n \in \mathbb{N}}$ be a sequence of global minimizers of the functional $J_n$ and let $F$ be such that $F_n\to F$ in $L^1$. We know that $F$ is a global minimizer of the perimeter and that by the choice of $m$ the lamella is not a global minimizer. Therefore it must hold $|E\triangle F|>0$.

\label{lemma a priori estimates}
	Let $\eta>0$ and let $E \subset \mathbb{T}^N$ be a strictly stable set. There exists $\delta>0$ with the following property: if $f_1, f_2\in C^1(\partial E)$ with $\|f_i\|_{C^1(\partial E)}\le \delta$ and $|E_{f_i}|=|E|$ for $i=1,2$ we have
	\begin{align}
		C_1(1-\eta)\|f_1-f_2\|_{L^2}^2\le &\mathcal D(E_{f_1},E_{f_2})\le C_1 (1+\eta)\|f_1-f_2\|_{L^2}^2\label{stima dissipazione norma 2}\\[2ex]
		\dfrac{1-\eta }2\int_{\partial {\textcolor{black}{E_{f_1}}}}\textnormal{sd}^2_{ E_{f_2}}\,\textnormal{d}\mathcal H^{N-1}\le &\mathcal D(E_{f_1},E_{f_2})\le \dfrac{1+\eta }2\int_{\partial {\textcolor{black}{E_{f_1}}}}\textnormal{sd}^2_{ E_{f_2}}\,\textnormal{d}\mathcal H^{N-1}\label{stima dissipazione distanza^2}\\[2ex]
		|\textnormal{bar}(E_{f_1})-\textnormal{bar}(E_{f_2})|^2\le& C_2\|f_1-f_2\|^2_{L^2} \le \frac{C_2}{C_1(1-\eta)}\mathcal D(E_{f_1},E_{f_2})
		\label{stima baricentri}
	\end{align}
	for suitable constants $C_1,\, C_2>0$.

Let $h>0$ and let $E \subset \mathbb{T}^N$ be a strictly stable set. There exist constants $C,$ $\delta>0$  with the following property: for any pair of normal deformations $E_{f_1},$ $E_{f_2}$ with $f_i\in C^2(\partial E),$ $\|f_i\|_{C^1(\partial E)}\le \delta$, and such that $|E_{f_2}|=|E|,$ $|\int_{\partial E}\nu_E f_2\,\textnormal{d} \mathcal H^{N-1}|\le \delta\|f_2\|_{L^2(\partial E)}$ and
	\begin{equation}
		H_{E_{f_2}}+\dfrac {\textnormal{sd}_{ E_{f_1}}}h=\lambda \quad \text{on}\quad \partial E_{f_2}
		\label{diss-diss euler lagrange}
	\end{equation}
	for some $\lambda\in\mathbb{R}$, we have
	\begin{equation}
		\mathcal D(E,E_{f_2})\le C\mathcal D(E_{f_2},E_{f_1}).
		\label{dissipation-dissipation inequality}
	\end{equation}
	\label{lemma 3.5}

By Theorem \ref{teo alex}, for $\delta$ sufficiently small, we get
    \begin{equation*}
        \begin{split}
            \|f_2\|_{L^2(\partial E)}^2 &\le C \|H_{E_{f_2}}-\overline{H}_{E_{f_2}}\|_{L^2(\partial E)}^2\le C\|H_{E_{f_2}}-\lambda \|_{L^2(\partial E)}^2\\
            &\le 2 C \|H_{E_{f_2}}-\lambda \|_{L^2(\partial E_{f_2})}^2= \frac{2C}{h^2} \int_{\partial E_{f_2}} \textnormal{sd}_{E_{f_1}}^2 \,\textnormal{d}\mathcal H^{N-1},
        \end{split}
    \end{equation*}
    where the third inequality follows by bounding the Jacobian of the change of variables by $2$ (see \eqref{Jac_gen}). By combining the previous inequalities with \eqref{stima dissipazione norma 2} and \eqref{stima dissipazione distanza^2}, we obtain the thesis.

Let $h^*>0$, $\delta^*>0$ and $(\tau_n)_{n \in\mathbb{N}}$ be given by Proposition \ref{teorema convergenza a meno di traslazioni}. Fix $h<h^*$ and set $E_n:=E_h^n$. We split the proof in three steps.\\
	\textbf{Step 1.} (Exponential convergence of dissipations) Testing the minimality of $E_n$ with $E_{n-1}$ we obtain
	\[ P(E_n)+\dfrac 1h\mathcal D(E_n,E_{n-1})\le P(E_{n-1}). \]
	Recalling that $P(E_n)\to P(E)$ and summing the previous inequality from $n+1$ to $+\infty$ we get
	\begin{equation}
		\sum_{k=n+1}^{+\infty} \dfrac 1h\mathcal D(E_k,E_{k-1})\le  P(E_n)-P(E).
		\label{confronto facile2}
	\end{equation}

	We will now construct a suitable competitor to estimate the dissipation at the step $n-1$ with the difference of perimeters. 
	Since, by Proposition \ref{teorema convergenza a meno di traslazioni}, we have
	\begin{equation}
		E_n+\tau_n\to E   \quad \text{in} \quad C^k \quad \forall k \in \mathbb{N},
		\label{convergenza}
	\end{equation}
	the translated sets of the flow, for $n$ large enough, can be written as normal deformations of the set $E$, that is there exists $g_n : \partial E\to \mathbb{R}$ such that
	\[ E_n+\tau_n=E_{g_n}, \]
	where $E_{g_n}$ was defined in \eqref{normal_deformation}.
	The convergence \eqref{convergenza} then reads as $g_n\to 0$ in $C^k$ as $n\to \infty$. Let $\sigma_n$ be the translations introduced by Lemma \ref{lemma 3.8_AFM} with $E_n +\tau_n$ instead of $F$. From the convergence in $C^k$ of $E_n+\tau_n$ to $E$, we deduce that $\sigma_n \to 0$ as $n\to\infty$. Therefore, setting 
	\[F_n:=E_n+\tau_n+\sigma_n,\]
	we have that $F_n\to E$ in $C^k$  and $F_n=E_{f_n}$ with $f_n:\partial E\to\mathbb{R}$ satisfying
	\[ \left|\int_{\partial E} f_n\nu_E \,\textnormal{d}\mathcal H^{N-1}\right|\le \delta\|f_n\|_{L^2(\partial E)}\quad \text{and}\quad \|f_n\|_{W^{2,p}(\partial E)}\le C \|g_n\|_{W^{2,p}(\partial E)}   \]
	for $p>N-1$. Consider now the competitor
	\[ \mathscr E_n:=E-\tau_{n-1}-\sigma_{n-1}. \]
	From the minimality of $E_n$ we easily deduce 
	\begin{equation}
		P(E_n)+\dfrac 1h \mathcal D(E_n, E_{n-1})\le  P(\mathscr E_n)+\dfrac 1h \mathcal D(\mathscr E_n,E_{n-1})=P(E)+\dfrac 1h\mathcal D(E,E_{n-1}+\tau_{n-1}+\sigma_{n-1})
		\label{confronto competitor}
	\end{equation}
	where we used the translational invariance of the dissipations. From Lemma \ref{lemma 3.5n} we obtain that the sequence  $E_{n-2}+\tau_{n-1}+\sigma_{n-1}$ converges in $C^k$ to the same limit of $E_{n-1}+\tau_{n-1}+\sigma_{n-1}$, that is to $E$. In particular, for $n$ large enough we can write $E_{n-2}+\tau_{n-1}+\sigma_{n-1}=E_\psi$ for a suitable function $\psi:\partial E\to \mathbb{R}$ (depending on $n$) and with $\|\psi\|_{C^1(\partial E)}$ small. From Lemma \ref{lemma 3.5} we can then estimate the right hand side of \eqref{confronto competitor} with
	\begin{align*}
		\mathcal D(E,E_{n-1}+\tau_{n-1}+\sigma_{n-1})=&\mathcal D(E,F_{n-1})=\mathcal D(E,E_{f_{n-1}})
		\le C\mathcal D(E_{f_{n-1}}, E_\psi)\\
		=&C\mathcal D(E_{n-1}+\tau_{n-1}+\sigma_{n-1},E_{n-2}+\tau_{n-1}+\sigma_{n-1})\\
		=&C\mathcal D(E_{n-1},E_{n-2}).
	\end{align*}
	From the previous inequality and \eqref{confronto competitor} we obtain
	\begin{equation}
		P(E_n)-P(E)=P(E_n)-P(\mathscr E_n)\le \dfrac Ch \mathcal D(E_{n-1},E_{n-2}).
		\label{risultato confronto competitor}
	\end{equation}
	Now, \eqref{confronto facile2} and \eqref{risultato confronto competitor} yield
	\begin{align*}
		\sum_{k=n-1}^{\infty} \dfrac 1h\mathcal D(E_k,E_{k-1})
		=& \sum_{k= n+1}^{\infty} \dfrac 1h\mathcal D(E_k,E_{k-1}) + \dfrac 1h\mathcal D(E_n,E_{n-1})+\dfrac 1h\mathcal D(E_{n-1},E_{n-2})\\
		\le& \dfrac {C+1}h \mathcal D(E_{n-1},E_{n-2})+\dfrac 1h\mathcal D(E_n,E_{n-1})\\
		\le& \dfrac{C+1}h \left( \mathcal D(E_{n-1},E_{n-2})+\mathcal D(E_n,E_{n-1})  \right).
	\end{align*}
	We then apply Lemma \ref{lemma 3.10} below (with $l=2$) to conclude 
	\begin{equation}
		\mathcal D(E_n,E_{n-1})\le \left( 1-\dfrac 1{C+1} \right)^{n/2} \left(  P(E_0)- P(E) \right).
		\label{convergenza dissipazioni}
	\end{equation}
	\\
	\textbf{Step 2.} (Exponential convergence of barycenters)
	Set 
	\begin{equation}
		b= \left( 1-\dfrac 1{C+1} \right)^{\frac 14}\in(0,1).
		\label{def b}
	\end{equation} 
	From \eqref{convergenza}  and Lemma \ref{lemma 3.5n} both the sequences $(E_n+\tau_n)_{n\in\mathbb{N}}$ and $(E_{n-1}+\tau_n)_{n\in\mathbb{N}}$ converge in $C^k$ to $E$. Therefore, for $n$ large enough, there exist some functions $f_{1,n},\, f_{2,n}\in C^k(\partial E)$ such that 
	\[ E_{n}+\tau_n=E_{f_{1,n}},\quad E_{n-1}+\tau_n=E_{f_{2,n}} \]
	and $\|f_{i,n}\|_{C^k(\partial E)}\to 0$ as $n\to \infty$ for $i=1,2$. From \eqref{stima baricentri} and \eqref{convergenza dissipazioni}  we can estimate for $n$ sufficiently large
	\begin{align*}
		|\text{bar}(E_n)- \text{bar}(E_{n-1})|&=|\text{bar}(E_n+\tau_n)- \text{bar}(E_{n-1}+\tau_n)|\\
		&=|\text{bar}(E_{f_{1,n}})- \text{bar}(E_{f_{2,n}})|\\
		&\le C\sqrt{\mathcal D(E_{f_{1,n}},E_{f_{2,n}})}=\sqrt{\mathcal D(E_n,E_{n-1})}\\
		&\le C\left( P(E_0)-P(E)  \right)^{1/2}b^n.
	\end{align*}
	In turn, the above estimate implies that $(\text{bar}(E_n))_{n\in\mathbb{N}}$ satisfies the Cauchy condition, thus the whole sequence admits a limit $\bar \xi\in\mathbb{T}^N$. Moreover, the convergence is exponentially fast in the sense that 
	\[ |\text{bar}(E_{f_{1,n}})-\bar \xi|\le \sum_{k=n+1}^\infty |\text{bar}(E_{f_{1,n}})-\text{bar}(E_{f_{2,n}})|\le C\left( P(E_0)-P(E)  \right)^{1/2}\dfrac {b^n}{1-b}  \]
	for $n$ large enough. 
	Recalling \eqref{convergenza} we thus conclude that there exists a suitable translation $\xi \in \mathbb{T}^N$ such that for every $k\in\mathbb{N}$  
	\[ E_n\to E-\xi \quad \text{in }C^k \quad \text{as }n\to\infty.\]
	\textbf{Step 3.} (Exponential convergence of the sets) By the previous step we can write, for $n$ large, the boundaries of the evolving sets as radial graphs of the limit set $E-\xi$. Precisely, for $n$ large enough there exist functions $f_n$ such that
	\begin{equation}
		E_n+\xi=E_{f_n}\quad \text{and}\quad \|f_n\|_{C^k(\partial E)}\to 0 \quad \text{as }n\to\infty.
		\label{convergenza deformazioni}
	\end{equation}
	From \eqref{stima dissipazione norma 2} and for $n$ large enough we have $\|f_n-f_{n-1}\|_{L^2(\partial E)}\le 2\sqrt{\mathcal D(E_n,E_{n-1})}$ and thus, recalling \eqref{convergenza dissipazioni} and arguing as in Step 2, we get
	\begin{equation}
		\|f_n\|_{L^2(\partial E)}\le \sum_{k=n+1}^\infty \|f_n-f_{n-1}\|_{L^2(\partial E)}\le \left(  P(E_0)-P(E)  \right)^{1/2} \dfrac {b^n}{1-b}
		\label{velocita convergenza}
	\end{equation}
	where $b$ is as in \eqref{def b}. The above estimate yields the exponential decay of the $L^2-$norms of the radial graphs. We recall the well-known Gagliardo-Nieremberg inequality: for every $j\in\mathbb{N}$ there exists $C>0$ such that, if $g$ is smooth enough on the boundary of a smooth set $E$, then 
	\begin{equation}
		\| D^k g \|_{L^2(\partial E)}\le C\| D^{2k}g\|^{1/2}_{L^2(\partial E)}\|g\|^{1/2}_{L^2(\partial E)} 
		\label{gagliardo-nieremberg}
	\end{equation}
	where $D^k$ stands for the collection of all the $k-$th order derivatives of $g$, see e.g. \cite[Theorem~3.70]{Aub}.
	Now, by \eqref{convergenza deformazioni} for every $k$ there exists $n_k$ such that $\sup_{n\ge n_k}\| D^{2k} f_n\|_{L^2(\partial E)}\le 1$, therefore we may apply \eqref{gagliardo-nieremberg} to $f_n$ to deduce from \eqref{velocita convergenza} that also $\| D^k f_n\|_{L^2(\partial E)}$ decays exponentially fast for all $k\in\mathbb{N}$. The Sobolev immersion Theorem then yields the exponential decay in $C^k$ for every $k$ thus completing the proof of the result.

\label{remark scrittura lamelle}
	We remark that for every $ \varepsilon>0$ there exists $ n_0=n_0(\varepsilon)\in \mathbb{N}$ such that for every $n\ge n_0 $ it holds 
	\begin{equation}
		\label{scrittura insiemi flusso}
		|E_n\triangle \bigcup_{i=1}^{l_n} F_{i,n} |\le \varepsilon \quad \text{or} \quad |E_n^c\triangle \bigcup_{i=1}^{L_n} F_{i,n} |\le \varepsilon,
	\end{equation}
	where, in the first case, $\bigcup_{i=1}^{l_n} F_{i,n}$ is a union of disjoint lamellae or a union of disjoint discs, with $F_{i,n}$ having the same mass of the $i-$th connected component of $E_n$; $l_n$ is either {\textcolor{black}{less than or equal to}} $ P_\infty/2$ if $F_{i,n},\ i=1,\dots, l_n$, are lamellae or $l_n=\pi^{-1} P_{\infty}^2/(4m)$ if they are discs; in the second case, $\bigcup_{i=1}^{L_n} F_{i,n}$ is a union of disjoint discs, with $F_{i,n}$ having the same mass of the $i-$th connected component of $E_n^c$ and $L_n=\pi^{-1} P_{\infty}^2/(4-4m)$.
	This can be easily proved recalling that any subsequence of the flow admits a further subsequence converging in $L^1$ to a set of the aforementioned form.


	Moreover, the classical regularity theory of $\Lambda-$minimizers implies that the previous result can be improved. Consider, for the sake of simplicity, that $E_n$ satisfies the first inequality in \eqref{scrittura insiemi flusso}(the other case is analogous). Then one can prove that for every $ \varepsilon>0$ there exists $ n_0=n_0(\varepsilon)$ such that for every $n\ge n_0 $ it holds
	\begin{equation}
		E_n=\bigcup_{i=1}^{l_n} (F_{i,n})_{f_{i,n}} \quad \text{where} \quad f_{i,n}\in C^{1,\alpha}(\partial F_{i,n}), \ \|f_{i,n}\|_{C^{1,\alpha}(\partial F_{i,n})}\le \varepsilon.
		\label{scrittura lamelle}
	\end{equation}

\label{rmk lamellae}
    {\textcolor{black}{In this remark, we identify $\mathbb{T}^2$ with the unit square $[0,1)^2.$
    We prove that for a fixed $M>0$ there exists a finite number of slopes such that, for any lamella $L$ having one of those slopes, we have $P(L)\le M$.}}

    {\textcolor{black}{Fix a lamella $L$. Let $a \subset \mathbb{T}^2$ be one of the two components of the boundary of $L$, and suppose that $(0,0) \in a$. Since $a$ is a closed curve in $\mathbb{T}^2$, by periodicity, the line in $\mathbb{R}^2$ passing through the origin and with the same slope of $a$ must  also pass through a point of the form $(p,q) \in \mathbb{N} \times \mathbb{N}$ with $p,q$ coprime or equal to $(0,1)$ or $(1,0)$.  We then remark that the length in $\mathbb{T}^2$ of $a$ is equal to the one of the segment between the origin and $(p,q)$, that is length$(a)=|(p,q)|.$ 
    \begin{figure}
        \centering
        \includegraphics[scale=0.4]{lamellae.png}
        \caption{The lamella $L$ in light blue, the line $a$  dashed in red.}
    \end{figure}
    Since $P(L)=2\,\text{length}(a)$, in order to have $P(L) \le M$, the point $(p,q)$ must be contained in the disc of radius $M/2$.
    Our claim follows since in the disc of radius $M/2$ there is a finite number of points belonging to $\mathbb{N} \times \mathbb{N}$.}}

\label{limite unico}
	Fix $h$, $ m>0$ and an initial set $ E_0 \subset \mathbb{T}^2$ with mass $m$.
	Let $(E_n)_{n \in \mathbb{N}}$ be a discrete flow starting from $E_0$. 
	Then either one of the following holds:
	\begin{itemize}

		\item[i)] the limit points of the flow are disjoint unions of $l$ discs of total area $m$, where $l=\pi^{-1} (4m)^{-1}P_{\infty}^2$ belongs to $\mathbb{N}$,
		\item[ii)] the limit points of the flow are the complement of disjoint unions of $l$ discs of total area $1-m$, where $l=\pi^{-1} (4-4m)^{-1}P_{\infty}^2$ belongs to $\mathbb{N}$.
		\item[iii)] {\textcolor{black}{the limit points of the flow are disjoint unions of $l$ lamellae of total area $m$, with the same slope and $l \le P_\infty/2$. Moreover, the equality $l=P_{\infty}/2 \in \mathbb{N}$ holds if and only if the limit is given by vertical or horizontal lamellae.}}
	\end{itemize}

We first employ a compactness argument and then use Lemma \ref{lemma 3.5n} to conclude. We start by fixing some notation. We denote by
	\begin{equation}
		\label{def unione palle}
		\mathscr E_B:= \bigcup_{i=1}^{l_B} B_i
	\end{equation}
	any disjoint union of $l_B=4^{-1}\pi m^{-1}P_{\infty}^2 $ discs each having radius $2m/P_{\infty}$; we denote by
	\begin{equation}
		\label{def unione palle compl}
		\mathscr E_{B^c}:= \left (\bigcup_{i=1}^{l_{B^c}} B_i\right )^c 
	\end{equation}
	the complement of any disjoint union of $l_{B^c}=4^{-1}\pi (1-m)^{-1}P_{\infty}^2 $ discs, each of radius $2(1-m)/P_{\infty}$; we denote by 
	\begin{equation}
		\label{def unione lamelle}
		\mathscr E_L:= \bigcup_{i=1}^{l_L} L_i
	\end{equation}
	any disjoint union of $l_L{\textcolor{black}{\le\  }}P_{\infty}/2$ lamellae {\textcolor{black}{having the same slope}} ({\textcolor{black}{and}} possibly having different masses). We remark that, for every fixed $P_\infty$ and $m$, the following holds
	\begin{equation}
		i:=\inf\{ \,\textnormal{d}_H( \mathscr E_B, \mathscr E_L)\wedge \,\textnormal{d}_H( \mathscr E_{B^c}, \mathscr E_L) \wedge \,\textnormal{d}_H( \mathscr E_{B^c}, \mathscr E_B) \ :\ \mathscr E_L, \mathscr E_B, \mathscr E_{B^c} \text{ as above}  \}>0,
		\label{distanza palle-lamelle}
	\end{equation}
	{\textcolor{black}{This is clear if we compare the families $\mathscr E_B, \mathscr E_{B^c}$ and a union of lamellae having the same slope. Since, by  Remark \ref{rmk lamellae}, there is a finite number of possible slopes for the lamellae, we conclude \eqref{distanza palle-lamelle}.}} From Remark \ref{remark scrittura lamelle} the discrete flow is eventually $C^1-$close to a limit point of the form $\mathscr E_L, \mathscr E_B$ or $\mathscr E_{B^c}$.  Assume now by contradiction that the flow does not converge to a fixed configuration. Then, without loss of generality, we can assume that for every $0<\varepsilon<i/3$ there exist infinitely many indexes such that
	\[ \,\textnormal{d}_H(E_{n-1},\mathscr E_B)\le \varepsilon \quad \text{and }\quad \,\textnormal{d}_H(E_{n},\mathscr E_L)\le \varepsilon.\]
	Therefore we get
	\[ \,\textnormal{d}_H(\mathscr E_B,\mathscr E_L)\le \,\textnormal{d}_H(\mathscr E_B, E_{n-1})+\,\textnormal{d}_H(\mathscr E_L,E_n)+\,\textnormal{d}_H(E_n,E_{n-1})\le 2\varepsilon+\,\textnormal{d}_H(E_n,E_{n-1}).  \]
	To reach the contradiction (compare \eqref{distanza palle-lamelle}), it is enough to show that  for every $ \varepsilon>0$ there exists $  n_0=n_0(\varepsilon)$ such that for every $n\ge n_0 $ it holds
	\begin{equation}
		\,\textnormal{d}_H (E_{n-1},E_n)\le \varepsilon.
		\label{lemma 3.5 implica}
	\end{equation}
	Assume by contradiction the existence of a subsequence $n_k$ along which the flow satisfies
	\[\,\textnormal{d}_H (E_{n_k-1},E_{n_k})> \varepsilon.\]
	Up to a further subsequence, $E_{n_k}\to F$, with $F$ being a set of the form $\mathscr E_B, \mathscr E_L $ or $\mathscr E_{B^c}$. But then Lemma \ref{lemma 3.5n} implies $ \textnormal{sd}_{E_{n_k-1}}\to \textnormal{sd}_F$ uniformly, which is clearly a contradiction.

 {\textcolor{black}{Finally, we observe that in case $iii)$ the number of connected component is given by $\frac{P_{\infty}}{2|(p,q)|}$, where we used the same notation of Remark \ref{rmk lamellae}. Thus, $l=P_\infty/2$ if and only if $(p,q)$ is equal to $(0,1)$ or to $(1,0)$

 that means that the lamella is either vertical or horizontal.}}

The proof of equations \eqref{stima dissipazione norma 2} and \eqref{stima dissipazione distanza^2} are quite analogous to the corresponding ones in \cite{MPS}. We recall it for the sake of completeness and to highlight the minor differences between the two versions.


	We start by observing that for any $\eta'>0$, if $\delta$ is sufficiently small, then for every $p_0\in\partial E_{f_2}$ the boundary of $E_{f_2}$ in a small disc must be contained in a cone 
	\begin{equation}
		\partial E_{f_2}\cap B_{4\bar\delta}(p_0)\subset G:=\left\lbrace  y\in\mathbb{R}^N\ :|(y-p_0)\cdot \nu_E(p_0)|^2\le \dfrac{\eta'^2}{1+\eta'^2} |y-p_0|^2  \right\rbrace. 
		\label{cono}
	\end{equation}
	We then divide the rest of the proof into two steps.\\
	\textbf{Step 1.} If $\delta$ is small enough , for every point $p=\lambda p_0\in B_{2\delta}(p_0)\ (\lambda>0),$ we have that 
	\[ \dfrac 1{1+\eta'}|p-p_0|\le \textnormal{dist}(p,\partial E_{f_2})\le |p-p_0|.  \]
	Indeed the second inequality is trivial by definition, since $p_0\in\partial E_{f_2}$. Concerning the first one, set $q\in\partial E_{f_2}$ such that $\textnormal{dist}(p,\partial E_{f_2})=|p-q|$, in particular $|p-q|\le |p-p_0|\le 2\delta$. From \eqref{cono} we infer that $q\in G$ and thus we have 
	\[  \textnormal{dist}(p,\partial E_{f_2})\ge \textnormal{dist}(p,G)=\dfrac 1{\sqrt{1+\eta'^2}}|p-p_0|\ge \dfrac 1{1+\eta'}|p-p_0| \]
	where we used the explicit formula for the projection of a point on a cone. If $p_0:=s+f_2(s)\nu_E(s)\in\partial E_{f_2}$ with $s\in \partial E$, we set
	\[ p_t:=p_0+t\dfrac {f_1(s)-f_2(s)}{|f_1(s)-f_2(s)|}\nu_E(s)\quad \text{for all } t\in [0,c|f_1(s)-f_2(s)|]  \]
	for an appropriate constant $c$ such that the quantities defined are regular. We deduce that 
	\begin{equation}
		\dfrac 1{1+\eta'}t\le \textnormal{dist}(p_t,\partial E_{f_2})\le t.
		\label{stima cose}
	\end{equation}
	Keeping the same notation and using the coarea formula (also recall \eqref{quiquo}), we infer that 
	\begin{align}
		\mathcal D(E_{f_1},E_{f_2})&=\int_{E_{f_1}\triangle E_{f_2}}\textnormal{dist}(x,\partial E_{f_2})\,\textnormal{d} x\nonumber\\
		&=\int_{\partial E}\,\textnormal{d}\mathcal H^{N-1}(s)\int_0^{c|f_1(s)-f_2(s)|} \textnormal{dist}(p_t, \partial E_{f_2})J\Phi(s,t) \,\textnormal{d} t\nonumber \\
		&=\int_{\partial E}\,\textnormal{d}\mathcal H^{N-1}(s)\int_0^{c|f_1(s)-f_2(s)|} \textnormal{dist}(p_t,\partial E_{f_2}) \,\textnormal{d} t \nonumber\\ 
		&\quad+\int_{\partial E}\,\textnormal{d}\mathcal H^{N-1}(s)\int_0^{c|f_1(s)-f_2(s)|}  \textnormal{dist}(p_t,\partial E_{f_2})(J\Phi(s,t)-1) \,\textnormal{d} t.
		\label{stima cose 2}
	\end{align}
	Recalling that for every $s \in \partial E$ we have that $J\Phi(s,\cdot)-1$ is Lipschitz continuous with constant $H_E$, for $\delta $ small enough and using \eqref{stima cose}, we get
	\begin{align}
		\mathcal D(E_{f_1},E_{f_2})&\le (1+\delta H_E)\int_{\partial E} \,\textnormal{d}\mathcal H^{N-1}(s) \int_0^{c|f_1(s)-f_2(s)|}t\,\textnormal{d} t\\
		&=\dfrac {1+\delta H_E}2 c^2\int_{\partial E}|f_1(s)-f_2(s)|^2 \,\textnormal{d}\mathcal H^{N-1}(s) ,   \label{stima cose 3}
	\end{align}
	from which the second inequality in \eqref{stima dissipazione norma 2} follows by taking  $\delta $ small enough. On the other hand, by \eqref{stima cose} we also have
	\begin{align}
		\mathcal D(E_{f_1},E_{f_2})&\ge \dfrac{1-\delta H_E}{1+\eta'}\int_{\partial E} \,\textnormal{d}\mathcal H^{N-1}(s) \int_0^{c|f_1(s)-f_2(s)|}t\,\textnormal{d} t\nonumber\\
		&=\dfrac {1-\delta H_E}{1+\eta'}c^2\int_{\partial E}|f_1(s)-f_2(s)|^2 \,\textnormal{d}\mathcal H^{N-1}(s),
		\label{stima cose 4}
	\end{align}
	from which the first inequality in \eqref{stima dissipazione norma 2} follows by taking $\eta'$ and  $\delta $ small enough.\\
	\textbf{Step 2.} The inequalities \eqref{stima dissipazione distanza^2} and \eqref{stima baricentri} are now easy consequences. Indeed, by \eqref{stima cose} we have that, for every $p_1=(1+f_1(s))\nu_E(s)\in\partial E_{f_1}$, it holds
	\[ \dfrac c{1+\eta'}|f_1(s)-f_2(s)|\le \textnormal{dist}(p_1,E_{f_2})\le c|f_1(s)-f_2(s)|.  \]
	Therefore \eqref{stima dissipazione distanza^2} follows from \eqref{stima cose 3} and \eqref{stima cose 4}, by taking $\eta'$ and $\delta$ smaller if needed and using the same  change of coordinates used previously (recall that $J\Phi$ and its inverse are estimated from above by $1+C\delta$ for a suitable constant $C>0$).

	Finally, we prove \eqref{stima baricentri}. For $\delta$ small enough, we can bound the Jacobian by $2$ and therefore we obtain
	\begin{align*}
		|\text{bar}(E_{f_1})-\text{bar}(E_{f_2})|\,|E|&=\left| \int_{E_{f_1}\setminus E_{f_2}}x\,\textnormal{d} x -\int_{E_{f_2}\setminus E_{f_1}}x \,\textnormal{d} x \right|\\
		&=\bigg| \int_{\partial E\cap \{f_1>f_2 \}}\,\textnormal{d}\mathcal H^{N-1}(s)\int_{f_2(s)} ^{f_1(s)} (s+t\nu_E(s))J\Phi(s)  \,\textnormal{d} t  \\
		&\,\,\, - \int_{\partial E\cap \{f_1<f_2\} }\,\textnormal{d}\mathcal H^{N-1}(s)\int_{f_1(s)} ^{f_2(s)} (s+t\nu_E(s))J\Phi(s) \,\textnormal{d} t \bigg|\\
		&\le 2\left |\int_{\partial E} \big(2s+(|f_1(s)|+|f_2(s)|) \nu_E(s)\big)\,|f_1(s)-f_2(s)|\,\textnormal{d}\mathcal H^{N-1}(s)\right|\\
		&    \le C\|f_1-f_2\|_{L^2}
	\end{align*}
	and the conclusion follows from \eqref{stima dissipazione norma 2}.
